(21, 'ask-directions', 'practice', '{"listening":[{"id":"ask-directions-listening-1","prompt":{"en":"Which phrase tells the driver the destination?","fr":"Quelle phrase indique la destination au chauffeur ?"},"target":"师傅，去这个酒店。","audio":"/audio/ask-directions/practice-listening-01.mp3","explanation":{"en":"This is the first taxi sentence to get moving from the airport.","fr":"C''est la première phrase de taxi pour partir de l''aéroport."}},{"id":"ask-directions-listening-2","prompt":{"en":"Which phrase asks to use the meter?","fr":"Quelle phrase demande d''utiliser le compteur ?"},"target":"请打表。","audio":"/audio/ask-directions/practice-listening-02.mp3","explanation":{"en":"请打表 is the key safety phrase before the taxi starts moving.","fr":"请打表 est la phrase de sécurité clé avant que le taxi ne démarre."}}],"speaking":[{"id":"ask-directions-speaking-1","prompt":{"en":"Tell the driver to go to this hotel.","fr":"Dis au chauffeur d''aller à cet hôtel."},"target":"师傅，去这个酒店。","audio":"/audio/ask-directions/practice-speaking-01.mp3","explanation":{"en":"You can swap 酒店 for 公寓 when going to an apartment.","fr":"Tu peux remplacer 酒店 par 公寓 si tu vas à un appartement."}},{"id":"ask-directions-speaking-2","prompt":{"en":"Ask the driver to use the meter.","fr":"Demande au chauffeur d''utiliser le compteur."},"target":"请打表。","audio":"/audio/ask-directions/practice-speaking-02.mp3","explanation":{"en":"A short 请 before an action keeps the request polite and simple.","fr":"Un 请 court avant une action garde la demande polie et simple."}}],"reading":[{"id":"ask-directions-reading-1","prompt":{"en":"Match the phrase that asks about travel time.","fr":"Associe la phrase qui demande la durée du trajet."},"target":"大概多久到？","audio":"/audio/ask-directions/practice-reading-01.mp3","explanation":{"en":"大概多久到 asks about the approximate arrival time.","fr":"大概多久到 demande l''heure ou la durée approximative d''arrivée."}},{"id":"ask-directions-reading-2","prompt":{"en":"Match the payment phrase.","fr":"Associe la phrase de paiement."},"target":"可以扫码吗？","audio":"/audio/ask-directions/practice-reading-02.mp3","explanation":{"en":"Recognize 扫码 as the scan-to-pay action.","fr":"Reconnais 扫码 comme l''action de scanner pour payer."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
