audio/order-food/practice-reading-02.mp3","explanation":{"en":"押金 is the deposit you may need to pay at check-in.","fr":"押金 est la caution que tu pourrais devoir payer au check-in."}}]}', 'draft', 33, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(35, 'order-food', 'reviewCards', '[{"id":"order-food-review-1","front":"我有预订","back":{"en":"I have a reservation.","fr":"J''ai une réservation."},"explanation":{"en":"Your opening sentence at the front desk.","fr":"Ta phrase d''ouverture à la réception."}},{"id":"order-food-review-2","front":"请出示护照","back":{"en":"Please show your passport.","fr":"Veuillez présenter votre passeport."},"explanation":{"en":"A common request during check-in.","fr":"Une demande courante pendant le check-in."}},{"id":"order-food-review-3","front":"房卡","back":{"en":"room card","fr":"carte de chambre"},"explanation":{"en":"The key card for your hotel room.","fr":"La carte clé de ta chambre d''hôtel."}},{"id":"order-food-review-4","front":"WiFi密码","back":{"en":"WiFi password","fr":"mot de passe WiFi"},"explanation":{"en":"Ask this right after check-in.","fr":"Demande ceci juste après le check-in."}},{"id":"order-food-review-5","front":"退房","back":{"en":"check out","fr":"check-out"},"explanation":{"en":"Know your checkout time.","fr":"Connais ton heure de check-out."}},{"id":"order-food-review-6","front":"押金","back":{"en":"deposit","fr":"caution"},"explanation":{"en":"You may need to pay this at the front desk.","fr":"Tu pourrais devoir payer ceci à la réception."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(36, 'order-food', 'reviewCards', '[{"id":"order-food-review-1","front":"我有预订","back":{"en":"I have a reservation.","fr":"J''ai une réservation."},"explanation":{"en":"Your opening sentence at the front desk.","fr":"Ta phrase d''ouverture à la réception."}},{"id":"order-food-review-2","front":"请出示护照","back":{"en":"Please show your passport.","fr":"Veuillez présenter votre passeport."},"explanation":{"en":"A common request during check-in.","fr":"Une demande courante pendant le check-in."}},{"id":"order-food-review-3","front":"房卡","back":{"en":"room card","fr":"carte de chambre"},"explanation":{"en":"The key card for your hotel room.","fr":"La carte clé de ta chambre d''hôtel."}},{"id":"order-food-review-4","front":"WiFi密码","back":{"en":"WiFi password","fr":"mot de passe WiFi"},"explanation":{"en":"Ask this right after check-in.","fr":"Demande ceci juste après le check-in."}},{"id":"order-food-review-5","front":"退房","back":{"en":"check out","fr":"check-out"},"explanation":{"en":"Know your checkout time.","fr":"Connais ton heure de check-out."}},{"id":"order-food-review-6","front":"押金","back":{"en":"deposit","fr":"caution"},"explanation":{"en":"You may need to pay this at the front desk.","fr":"Tu pourrais devoir payer ceci à la réception."}}]', 'draft', 35, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(37, 'phone-and-payment', 'lessonMeta', '{"id":"phone-and-payment","title":{"en":"Phone number & mobile payment setup","fr":"Téléphone & paiement mobile"},"scenario":{"en":"Ask for a SIM card, compare data plans, learn how to top up, and ask whether you can pay by phone or use cash first.","fr":"Demander une carte SIM, comparer les forfaits data, apprendre à recharger et demander si l''on peut payer avec son téléphone ou d''abord en espèces."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(38, 'phone-and-payment', 'lessonMeta', '{"id":"phone-and-payment","title":{"en":"Phone number & mobile payment setup","fr":"Téléphone & paiement mobile"},"scenario":{"en":"Ask for a SIM card, compare data plans, learn how to top up, and ask whether you can pay by phone or use cash first.","fr":"Demander une carte SIM, comparer les forfaits data, apprendre à recharger et demander si l''on peut payer avec son téléphone ou d''abord en espèces."}}', 'draft', 37, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(39, 'phone-and-payment', 'dialogue', '{"title":{"en":"Ask about phone and payment setup","fr":"Demander de l''aide pour le téléphone et le paiement"},"lines":[{"id":"phone-and-payment-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想办一张手机卡。","pinyin":"Nǐ hǎo, wǒ xiǎng bàn yì zhāng shǒujīkǎ.","translation":{"en":"Hello, I would like to get a SIM card.","fr":"Bonjour, je voudrais prendre une carte SIM."},"explanation":{"en":"我想办一张手机卡 keeps the request short and practical after check-in.","fr":"我想办一张手机卡 garde la demande courte et pratique après l''arrivée au logement."},"audio":"/audio/phone-and-payment/line-01.mp3"},{"id":"phone-and-payment-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，请出示护照。","pinyin":"Hǎo de, qǐng chūshì hùzhào.","translation":{"en":"Okay, please show your passport.","fr":"D''accord, veuillez présenter votre passeport."},"explanation":{"en":"This reuses the passport phrase from arrival in a phone setup context.","fr":"Cette phrase réutilise le mot passeport dans un contexte de téléphone."},"audio":"/audio/phone-and-payment/line-02.mp3"},{"id":"phone-and-payment-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"这个号码可以用来支付吗？","pinyin":"Zhège hàomǎ kěyǐ yòng lái zhīfù ma?","translation":{"en":"Can this number be used for payment?","fr":"Est-ce que ce numéro peut servir au paiement ?"},"explanation":{"en":"The learner hears 手机号码 and 支付 as a simple setup question, not a full payment guide.","fr":"L''apprenant entend 手机号码 et 支付 dans une question simple, sans guide complet de paiement."},"audio":"/audio/phone-and-payment/line-03.mp3"},{"id":"phone-and-payment-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，也可以先用现金。","pinyin":"Kěyǐ, yě kěyǐ xiān yòng xiànjīn.","translation":{"en":"Yes, and you can also use cash first.","fr":"Oui, et vous pouvez aussi utiliser des espèces d''abord."},"explanation":{"en":"现金 gives a safe fallback word if phone payment is not ready yet.","fr":"现金 donne un mot de secours si le paiement mobile n''est pas encore prêt."},"audio":"/audio/phone-and-payment/line-04.mp3"},{"id":"phone-and-payment-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"有什么流量套餐？","pinyin":"Yǒu shénme liúliàng tàocān?","translation":{"en":"What data plans do you have?","fr":"Quels forfaits data avez-vous ?"},"explanation":{"en":"Ask 有什么流量套餐 to compare data plan options at a phone shop.","fr":"Demande 有什么流量套餐 pour comparer les forfaits data dans une boutique."},"audio":"/audio/phone-and-payment/line-05.mp3"},{"id":"phone-and-payment-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有10G和30G的，你要哪个？","pinyin":"Yǒu shí G hé sānshí G de, nǐ yào nǎge?","translation":{"en":"We have 10G and 30G. Which one do you want?","fr":"Nous avons 10 Go et 30 Go. Lequel voulez-vous ?"},"explanation":{"en":"The clerk names two plan sizes and asks you to choose.","fr":"L''employé nomme deux tailles de forfait et te demande de choisir."},"audio":"/audio/phone-and-payment/line-06.mp3"},{"id":"phone-and-payment-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"怎么充值？","pinyin":"Zěnme chōngzhí?","translation":{"en":"How do I top up?","fr":"Comment recharger ?"},"explanation":{"en":"Ask 怎么充值 to learn how to add credit to your phone.","fr":"Demande 怎么充值 pour savoir comment ajouter du crédit à ton téléphone."},"audio":"/audio/phone-and-payment/line-07.mp3"},{"id":"phone-and-payment-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"好的，谢谢。","pinyin":"Hǎo de, xièxie.","translation":{"en":"Okay, thank you.","fr":"D''accord, merci."},"explanation":{"en":"A short closing phrase keeps the exchange beginner friendly.","fr":"Une formule de clôture courte garde l''échange accessible aux débutants."},"audio":"/audio/phone-and-payment/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
