:"/audio/phone-and-payment/practice-reading-02.mp3","explanation":{"en":"微信 is the most important app name to recognize in China.","fr":"微信 est le nom d''application le plus important à reconnaître en Chine."}}]}', 'draft', 45, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(47, 'phone-and-payment', 'reviewCards', '[{"id":"phone-and-payment-review-1","front":"手机卡","back":{"en":"SIM card / phone card","fr":"carte SIM / carte de téléphone"},"explanation":{"en":"Use this when asking for basic phone service.","fr":"Utilise ce mot pour demander un service téléphonique de base."}},{"id":"phone-and-payment-review-2","front":"手机号码","back":{"en":"phone number","fr":"numéro de téléphone"},"explanation":{"en":"This is the number attached to the phone or SIM card.","fr":"C''est le numéro lié au téléphone ou à la carte SIM."}},{"id":"phone-and-payment-review-3","front":"可以用手机支付吗？","back":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"A short practical question for shops and counters.","fr":"Une question courte et pratique dans les magasins et aux comptoirs."}},{"id":"phone-and-payment-review-4","front":"流量","back":{"en":"mobile data","fr":"données mobiles"},"explanation":{"en":"The word for mobile data.","fr":"Le mot pour les données mobiles."}},{"id":"phone-and-payment-review-5","front":"充值","back":{"en":"top up / recharge","fr":"recharger"},"explanation":{"en":"How to add credit to your phone.","fr":"Comment ajouter du crédit à ton téléphone."}},{"id":"phone-and-payment-review-6","front":"微信","back":{"en":"WeChat","fr":"WeChat"},"explanation":{"en":"The essential messaging and payment app.","fr":"L''application essentielle de messagerie et de paiement."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(48, 'phone-and-payment', 'reviewCards', '[{"id":"phone-and-payment-review-1","front":"手机卡","back":{"en":"SIM card / phone card","fr":"carte SIM / carte de téléphone"},"explanation":{"en":"Use this when asking for basic phone service.","fr":"Utilise ce mot pour demander un service téléphonique de base."}},{"id":"phone-and-payment-review-2","front":"手机号码","back":{"en":"phone number","fr":"numéro de téléphone"},"explanation":{"en":"This is the number attached to the phone or SIM card.","fr":"C''est le numéro lié au téléphone ou à la carte SIM."}},{"id":"phone-and-payment-review-3","front":"可以用手机支付吗？","back":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"A short practical question for shops and counters.","fr":"Une question courte et pratique dans les magasins et aux comptoirs."}},{"id":"phone-and-payment-review-4","front":"流量","back":{"en":"mobile data","fr":"données mobiles"},"explanation":{"en":"The word for mobile data.","fr":"Le mot pour les données mobiles."}},{"id":"phone-and-payment-review-5","front":"充值","back":{"en":"top up / recharge","fr":"recharger"},"explanation":{"en":"How to add credit to your phone.","fr":"Comment ajouter du crédit à ton téléphone."}},{"id":"phone-and-payment-review-6","front":"微信","back":{"en":"WeChat","fr":"WeChat"},"explanation":{"en":"The essential messaging and payment app.","fr":"L''application essentielle de messagerie et de paiement."}}]', 'draft', 47, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(49, 'convenience-store-run', 'lessonMeta', '{"id":"convenience-store-run","title":{"en":"First convenience store run","fr":"Première course en supérette"},"scenario":{"en":"Buy a bottle of water and a snack, say you do not need anything else, ask the total, pay by phone, and ask for a bag.","fr":"Acheter une bouteille d''eau et un snack, dire que l''on n''a besoin de rien d''autre, demander le total, payer par téléphone et demander un sac."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(50, 'convenience-store-run', 'lessonMeta', '{"id":"convenience-store-run","title":{"en":"First convenience store run","fr":"Première course en supérette"},"scenario":{"en":"Buy a bottle of water and a snack, say you do not need anything else, ask the total, pay by phone, and ask for a bag.","fr":"Acheter une bouteille d''eau et un snack, dire que l''on n''a besoin de rien d''autre, demander le total, payer par téléphone et demander un sac."}}', 'draft', 49, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(51, 'convenience-store-run', 'dialogue', '{"title":{"en":"Buy one simple item","fr":"Acheter un article simple"},"lines":[{"id":"convenience-store-run-line-01","speaker":{"en":"Customer","fr":"Client"},"hanzi":"你好，我要一瓶水和一包薯片。","pinyin":"Nǐ hǎo, wǒ yào yì píng shuǐ hé yì bāo shǔpiàn.","translation":{"en":"Hello, I want a bottle of water and a bag of chips.","fr":"Bonjour, je voudrais une bouteille d''eau et un paquet de chips."},"explanation":{"en":"我要...和... combines two items with 和 in one short sentence.","fr":"我要...和... combine deux articles avec 和 dans une phrase courte."},"audio":"/audio/convenience-store-run/line-01.mp3"},{"id":"convenience-store-run-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，还要别的吗？","pinyin":"Hǎo de, hái yào bié de ma?","translation":{"en":"Okay, do you want anything else?","fr":"D''accord, vous voulez autre chose ?"},"explanation":{"en":"还要别的吗 is a common checkout question after you name one item.","fr":"还要别的吗 est une question courante à la caisse après avoir nommé un article."},"audio":"/audio/convenience-store-run/line-02.mp3"},{"id":"convenience-store-run-line-03","speaker":{"en":"Customer","fr":"Client"},"hanzi":"不要了，一共多少钱？","pinyin":"Bú yào le, yígòng duōshao qián?","translation":{"en":"No more, how much is it altogether?","fr":"Rien d''autre, ça fait combien au total ?"},"explanation":{"en":"不要了 closes the shopping list, and 一共多少钱 asks the total price.","fr":"不要了 ferme la liste d''achats, et 一共多少钱 demande le prix total."},"audio":"/audio/convenience-store-run/line-03.mp3"},{"id":"convenience-store-run-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"九块钱。","pinyin":"Jiǔ kuài qián.","translation":{"en":"Nine yuan.","fr":"Neuf yuans."},"explanation":{"en":"块 is the everyday word you will hear for yuan in small purchases.","fr":"块 est le mot courant que tu entendras pour yuan dans les petits achats."},"audio":"/audio/convenience-store-run/line-04.mp3"},{"id":"convenience-store-run-line-05","speaker":{"en":"Customer","fr":"Client"},"hanzi":"可以用手机支付吗？","pinyin":"Kěyǐ yòng shǒujī zhīfù ma?","translation":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"This reuses the phone payment question from the previous lesson in a store.","fr":"Cette phrase réutilise la question de paiement mobile de la leçon précédente dans un magasin."},"audio":"/audio/convenience-store-run/line-05.mp3"},{"id":"convenience-store-run-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，扫码这里。","pinyin":"Kěyǐ, sǎomǎ zhèlǐ.","translation":{"en":"Yes, scan here.","fr":"Oui, scannez ici."},"explanation":{"en":"扫码这里 points to the QR code on the counter or screen.","fr":"扫码这里 indique le code QR sur le comptoir ou l''écran."},"audio":"/audio/convenience-store-run/line-06.mp3"},{"id":"convenience-store-run-line-07","speaker":{"en":"Customer","fr":"Client"},"hanzi":"有袋子吗？","pinyin":"Yǒu dàizi ma?","translation":{"en":"Do you have a bag?","fr":"Avez-vous un sac ?"},"explanation":{"en":"Ask 有袋子吗？ if you need a plastic bag for your items.","fr":"Demande 有袋子吗？ si tu as besoin d''un sac plastique pour tes articles."},"audio":"/audio/convenience-store-run/line-07.mp3"},{"id":"convenience-store-run-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有，两毛钱。","pinyin":"Yǒu, liǎng máo qián.","translation":{"en":"Yes, twenty cents.","fr":"Oui, vingt centimes."},"explanation":{"en":"Bags in some Chinese stores cost a small extra fee.","fr":"Les sacs dans certains magasins chinois coûtent un petit supplément."},"audio":"/audio/convenience-store-run/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(52, 'convenience-store-run', 'dialogue', '{"title":{"en":"Buy one simple item","fr":"Acheter un article simple"},"lines":[{"id":"convenience-store-run-line-01","speaker":{"en":"Customer","fr":"Client"},"hanzi":"你好，我要一瓶水和一包薯片。","pinyin":"Nǐ hǎo, wǒ yào yì píng shuǐ hé yì bāo shǔpiàn.","translation":{"en":"Hello, I want a bottle of water and a bag of chips.","fr":"Bonjour, je voudrais une bouteille d''eau et un paquet de chips."},"explanation":{"en":"我要...和... combines two items with 和 in one short sentence.","fr":"我要...和... combine deux articles avec 和 dans une phrase courte."},"audio":"/audio/convenience-store-run/line-01.mp3"},{"id":"convenience-store-run-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，还要别的吗？","pinyin":"Hǎo de, hái yào bié de ma?","translation":{"en":"Okay, do you want anything else?","fr":"D''accord, vous voulez autre chose ?"},"explanation":{"en":"还要别的吗 is a common checkout question after you name one item.","fr":"还要别的吗 est une question courante à la caisse après avoir nommé un article."},"audio":"/audio/convenience-store-run/line-02.mp3"},{"id":"convenience-store-run-line-03","speaker":{"en":"Customer","fr":"Client"},"hanzi":"不要了，一共多少钱？","pinyin":"Bú yào le, yígòng duōshao qián?","translation":{"en":"No more, how much is it altogether?","fr":"Rien d''autre, ça fait combien au total ?"},"explanation":{"en":"不要了 closes the shopping list, and 一共多少钱 asks the total price.","fr":"不要了 ferme la liste d''achats, et 一共多少钱 demande le prix total."},"audio":"/audio/convenience-store-run/line-03.mp3"},{"id":"convenience-store-run-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"九块钱。","pinyin":"Jiǔ kuài qián.","translation":{"en":"Nine yuan.","fr":"Neuf yuans."},"explanation":{"en":"块 is the everyday word you will hear for yuan in small purchases.","fr":"块 est le mot courant que tu entendras pour yuan dans les petits achats."},"audio":"/audio/convenience-store-run/line-04.mp3"},{"id":"convenience-store-run-line-05","speaker":{"en":"Customer","fr":"Client"},"hanzi":"可以用手机支付吗？","pinyin":"Kěyǐ yòng shǒujī zhīfù ma?","translation":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"This reuses the phone payment question from the previous lesson in a store.","fr":"Cette phrase réutilise la question de paiement mobile de la leçon précédente dans un magasin."},"audio":"/audio/convenience-store-run/line-05.mp3"},{"id":"convenience-store-run-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，扫码这里。","pinyin":"Kěyǐ, sǎomǎ zhèlǐ.","translation":{"en":"Yes, scan here.","fr":"Oui, scannez ici."},"explanation":{"en":"扫码这里 points to the QR code on the counter or screen.","fr":"扫码这里 indique le code QR sur le comptoir ou l''écran."},"audio":"/audio/convenience-store-run/line-06.mp3"},{"id":"convenience-store-run-line-07","speaker":{"en":"Customer","fr":"Client"},"hanzi":"有袋子吗？","pinyin":"Yǒu dàizi ma?","translation":{"en":"Do you have a bag?","fr":"Avez-vous un sac ?"},"explanation":{"en":"Ask 有袋子吗？ if you need a plastic bag for your items.","fr":"Demande 有袋子吗？ si tu as besoin d''un sac plastique pour tes articles."},"audio":"/audio/convenience-store-run/line-07.mp3"},{"id":"convenience-store-run-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有，两毛钱。","pinyin":"Yǒu, liǎng máo qián.","translation":{"en":"Yes, twenty cents.","fr":"Oui, vingt centimes."},"explanation":{"en":"Bags in some Chinese stores cost a small extra fee.","fr":"Les sacs dans certains magasins chinois coûtent un petit supplément."},"audio":"/audio/convenience-store-run/line-08.mp3"}]}', 'draft', 51, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(53, 'convenience-store-run', 'sentencePatterns', '[{"id":"convenience-store-run-pattern-1","pattern":"我要……","meaning":{"en":"I want ...","fr":"Je veux / je voudrais ..."},"example":"我要一瓶水。","audio":"/audio/convenience-store-run/pattern-01.mp3","explanation":{"en":"Use it for one simple item when the context is already clear.","fr":"Utilise cette structure pour un article simple quand le contexte est clair."}},{"id":"convenience-store-run-pattern-2","pattern":"还要……吗？","meaning":{"en":"Do you also want ...?","fr":"Voulez-vous aussi ... ?"},"example":"还要别的吗？","audio":"/audio/convenience-store-run/pattern-02.mp3","explanation":{"en":"This is a common question from a clerk before payment.","fr":"C''est une question courante de l''employé avant le paiement."}},{"id":"convenience-store-run-pattern-3","pattern":"一共多少钱？","meaning":{"en":"How much is it altogether?","fr":"Combien ça fait au total ?"},"example":"一共多少钱？","audio":"/audio/convenience-store-run/pattern-03.mp3","explanation":{"en":"Ask this when you are ready to pay for the purchase.","fr":"Demande cela quand tu es prêt à payer l''achat."}},{"id":"convenience-store-run-pattern-4","pattern":"我要……和……","meaning":{"en":"I want ... and ...","fr":"Je voudrais ... et ..."},"example":"我要一瓶水和一包薯片。","audio":"/audio/convenience-store-run/pattern-04.mp3","explanation":{"en":"Use 和 to list two items in one sentence at a store.","fr":"Utilise 和 pour énumérer deux articles dans une phrase au magasin."}},{"id":"convenience-store-run-pattern-5","pattern":"有……吗？","meaning":{"en":"Do you have ...?","fr":"Avez-vous ... ?"},"example":"有袋子吗？","audio":"/audio/convenience-store-run/pattern-05.mp3","explanation":{"en":"Use 有…吗 to check if an item or service is available.","fr":"Utilise 有…吗 pour vérifier si un article ou un service est disponible."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(54, 'convenience-store-run', 'sentencePatterns', '[{"id":"convenience-store-run-pattern-1","pattern":"我要……","meaning":{"en":"I want ...","fr":"Je veux / je voudrais ..."},"example":"我要一瓶水。","audio":"/audio/convenience-store-run/pattern-01.mp3","explanation":{"en":"Use it for one simple item when the context is already clear.","fr":"Utilise cette structure pour un article simple quand le contexte est clair."}},{"id":"convenience-store-run-pattern-2","pattern":"还要……吗？","meaning":{"en":"Do you also want ...?","fr":"Voulez-vous aussi ... ?"},"example":"还要别的吗？","audio":"/audio/convenience-store-run/pattern-02.mp3","explanation":{"en":"This is a common question from a clerk before payment.","fr":"C''est une question courante de l''employé avant le paiement."}},{"id":"convenience-store-run-pattern-3","pattern":"一共多少钱？","meaning":{"en":"How much is it altogether?","fr":"Combien ça fait au total ?"},"example":"一共多少钱？","audio":"/audio/convenience-store-run/pattern-03.mp3","explanation":{"en":"Ask this when you are ready to pay for the purchase.","fr":"Demande cela quand tu es prêt à payer l''achat."}},{"id":"convenience-store-run-pattern-4","pattern":"我要……和……","meaning":{"en":"I want ... and ...","fr":"Je voudrais ... et ..."},"example":"我要一瓶水和一包薯片。","audio":"/audio/convenience-store-run/pattern-04.mp3","explanation":{"en":"Use 和 to list two items in one sentence at a store.","fr":"Utilise 和 pour énumérer deux articles dans une phrase au magasin."}},{"id":"convenience-store-run-pattern-5","pattern":"有……吗？","meaning":{"en":"Do you have ...?","fr":"Avez-vous ... ?"},"example":"有袋子吗？","audio":"/audio/convenience-store-run/pattern-05.mp3","explanation":{"en":"Use 有…吗 to check if an item or service is available.","fr":"Utilise 有…吗 pour vérifier si un article ou un service est disponible."}}]', 'draft', 53, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(55, 'convenience-store-run', 'vocabulary', '[{"id":"convenience-store-run-vocab-1","hanzi":"一瓶水","pinyin":"yì píng shuǐ","audio":"/audio/convenience-store-run/vocab-01.mp3","meaning":{"en":"a bottle of water","fr":"une bouteille d''eau"},"explanation":{"en":"A useful first purchase item after arriving.","fr":"Un premier achat utile après l''arrivée."}},{"id":"convenience-store-run-vocab-2","hanzi":"还要别的吗","pinyin":"hái yào bié de ma","audio":"/audio/convenience-store-run/vocab-02.mp3","meaning":{"en":"anything else?","fr":"autre chose ?"},"explanation":{"en":"Listen for this checkout question after naming your item.","fr":"Écoute cette question à la caisse après avoir nommé ton article."}},{"id":"convenience-store-run-vocab-3","hanzi":"不要了","pinyin":"bú yào le","audio":"/audio/convenience-store-run/vocab-03.mp3","meaning":{"en":"no more / nothing else","fr":"rien d''autre"},"explanation":{"en":"Use it to say you do not need anything else.","fr":"Utilise-le pour dire que tu n''as besoin de rien d''autre."}},{"id":"convenience-store-run-vocab-4","hanzi":"一共","pinyin":"yígòng","audio":"/audio/convenience-store-run/vocab-04.mp3","meaning":{"en":"altogether / in total","fr":"au total"},"explanation":{"en":"This word prepares the total price question.","fr":"Ce mot prépare la question du prix total."}},{"id":"convenience-store-run-vocab-5","hanzi":"多少钱","pinyin":"duōshao qián","audio":"/audio/convenience-store-run/vocab-05.mp3","meaning":{"en":"how much money?","fr":"combien d''argent ? / combien ça coûte ?"},"explanation":{"en":"The key phrase for asking a simple price.","fr":"La phrase clé pour demander un prix simple."}},{"id":"convenience-store-run-vocab-6","hanzi":"薯片","pinyin":"shǔpiàn","audio":"/audio/convenience-store-run/vocab-06.mp3","meaning":{"en":"potato chips","fr":"chips"},"explanation":{"en":"A common snack to buy in convenience stores.","fr":"Un snack courant à acheter en supérette."}},{"id":"convenience-store-run-vocab-7","hanzi":"袋子","pinyin":"dàizi","audio":"/audio/convenience-store-run/vocab-07.mp3","meaning":{"en":"bag","fr":"sac"},"explanation":{"en":"Ask for a 袋子 if you need something to carry your items.","fr":"Demande un 袋子 si tu as besoin de porter tes articles."}},{"id":"convenience-store-run-vocab-8","hanzi":"扫码","pinyin":"sǎomǎ","audio":"/audio/convenience-store-run/vocab-08.mp3","meaning":{"en":"scan code / scan to pay","fr":"scanner le code / scanner pour payer"},"explanation":{"en":"The clerk points to the QR code and says this.","fr":"L''employé montre le code QR et dit ceci."}},{"id":"convenience-store-run-vocab-9","hanzi":"毛","pinyin":"máo","audio":"/audio/convenience-store-run/vocab-09.mp3","meaning":{"en":"dime / one-tenth of a yuan","fr":"dixième de yuan"},"explanation":{"en":"毛 is the smaller unit when a price is under one yuan.","fr":"毛 est la petite unité quand un prix est inférieur à un yuan."}},{"id":"convenience-store-run-vocab-10","hanzi":"小票","pinyin":"xiǎopiào","audio":"/audio/convenience-store-run/vocab-10.mp3","meaning":{"en":"receipt","fr":"ticket de caisse"},"explanation":{"en":"The small receipt you get after paying at a store.","fr":"Le petit reçu que tu obtiens après avoir payé en magasin."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
