(57, 'convenience-store-run', 'practice', '{"listening":[{"id":"convenience-store-run-listening-1","prompt":{"en":"Listen for the phrase that means a bottle of water.","fr":"Écoute la phrase qui signifie une bouteille d''eau."},"target":"一瓶水","audio":"/audio/convenience-store-run/practice-listening-01.mp3","explanation":{"en":"一瓶水 is the item you are buying.","fr":"一瓶水 est l''article que tu achètes."}},{"id":"convenience-store-run-listening-2","prompt":{"en":"Which phrase asks for a bag?","fr":"Quelle phrase demande un sac ?"},"target":"有袋子吗？","audio":"/audio/convenience-store-run/practice-listening-02.mp3","explanation":{"en":"有袋子吗 checks if the store provides bags.","fr":"有袋子吗 vérifie si le magasin fournit des sacs."}}],"speaking":[{"id":"convenience-store-run-speaking-1","prompt":{"en":"Say you do not need anything else.","fr":"Dis que tu n''as besoin de rien d''autre."},"target":"不要了。","audio":"/audio/convenience-store-run/practice-speaking-01.mp3","explanation":{"en":"不要了 answers the clerk''s \"anything else?\" question.","fr":"不要了 répond à la question « autre chose ? » de l''employé."}},{"id":"convenience-store-run-speaking-2","prompt":{"en":"Ask if they have a bag.","fr":"Demande s''ils ont un sac."},"target":"有袋子吗？","audio":"/audio/convenience-store-run/practice-speaking-02.mp3","explanation":{"en":"A short practical question when buying several items.","fr":"Une question pratique et courte quand on achète plusieurs articles."}}],"reading":[{"id":"convenience-store-run-reading-1","prompt":{"en":"Choose the phrase for asking the total price.","fr":"Choisis la phrase pour demander le prix total."},"target":"一共多少钱？","audio":"/audio/convenience-store-run/practice-reading-01.mp3","explanation":{"en":"一共多少钱？ asks how much the purchase costs altogether.","fr":"一共多少钱？ demande combien coûte l''achat au total."}},{"id":"convenience-store-run-reading-2","prompt":{"en":"Match the word for potato chips.","fr":"Associe le mot pour chips."},"target":"薯片","audio":"/audio/convenience-store-run/practice-reading-02.mp3","explanation":{"en":"薯片 is a common snack you will see on shelves.","fr":"薯片 est un snack courant que tu verras dans les rayons."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
