nvenience-store-run/practice-reading-02.mp3","explanation":{"en":"薯片 is a common snack you will see on shelves.","fr":"薯片 est un snack courant que tu verras dans les rayons."}}]}', 'draft', 57, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(59, 'convenience-store-run', 'reviewCards', '[{"id":"convenience-store-run-review-1","front":"一瓶水","back":{"en":"a bottle of water","fr":"une bouteille d''eau"},"explanation":{"en":"A practical first convenience store item.","fr":"Un premier article pratique en supérette."}},{"id":"convenience-store-run-review-2","front":"多少钱","back":{"en":"how much money?","fr":"combien ça coûte ?"},"explanation":{"en":"Use this to ask a simple price.","fr":"Utilise cette phrase pour demander un prix simple."}},{"id":"convenience-store-run-review-3","front":"不要了","back":{"en":"no more / nothing else","fr":"rien d''autre"},"explanation":{"en":"A short response when the clerk asks if you want anything else.","fr":"Une réponse courte quand l''employé demande si tu veux autre chose."}},{"id":"convenience-store-run-review-4","front":"薯片","back":{"en":"potato chips","fr":"chips"},"explanation":{"en":"A snack to grab at any convenience store.","fr":"Un snack à prendre dans n''importe quelle supérette."}},{"id":"convenience-store-run-review-5","front":"袋子","back":{"en":"bag","fr":"sac"},"explanation":{"en":"Ask for this when you buy several items.","fr":"Demande ceci quand tu achètes plusieurs articles."}},{"id":"convenience-store-run-review-6","front":"扫码","back":{"en":"scan to pay","fr":"scanner pour payer"},"explanation":{"en":"The payment action at the counter.","fr":"L''action de paiement au comptoir."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
