(73, 'metro-ticket', 'lessonMeta', '{"id":"metro-ticket","title":{"en":"Buy a metro ticket","fr":"Acheter un ticket de métro"},"scenario":{"en":"Ask how to get to People''s Square, confirm line two, buy one metro ticket, ask how many stops, check for a transfer, ask the price, and confirm the exit.","fr":"Demander comment aller à la Place du Peuple, confirmer la ligne 2, acheter un ticket de métro, demander le nombre de stations, vérifier une correspondance, demander le prix et confirmer la sortie."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(74, 'metro-ticket', 'lessonMeta', '{"id":"metro-ticket","title":{"en":"Buy a metro ticket","fr":"Acheter un ticket de métro"},"scenario":{"en":"Ask how to get to People''s Square, confirm line two, buy one metro ticket, ask how many stops, check for a transfer, ask the price, and confirm the exit.","fr":"Demander comment aller à la Place du Peuple, confirmer la ligne 2, acheter un ticket de métro, demander le nombre de stations, vérifier une correspondance, demander le prix et confirmer la sortie."}}', 'draft', 73, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(75, 'metro-ticket', 'dialogue', '{"title":{"en":"Ask for a route and ticket","fr":"Demander un itinéraire et un ticket"},"lines":[{"id":"metro-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"去人民广场怎么走？","pinyin":"Qù Rénmín Guǎngchǎng zěnme zǒu?","translation":{"en":"How do I get to People''s Square?","fr":"Comment aller à la Place du Peuple ?"},"explanation":{"en":"去……怎么走 is the basic route question for a station or place.","fr":"去……怎么走 est la question de base pour demander un itinéraire vers une station ou un lieu."},"audio":"/audio/metro-ticket/line-01.mp3"},{"id":"metro-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"坐二号线。","pinyin":"Zuò èr hào xiàn.","translation":{"en":"Take line two.","fr":"Prenez la ligne 2."},"explanation":{"en":"号线 names the numbered metro line.","fr":"号线 indique la ligne de métro numérotée."},"audio":"/audio/metro-ticket/line-02.mp3"},{"id":"metro-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我要一张去人民广场的票。","pinyin":"Wǒ yào yì zhāng qù Rénmín Guǎngchǎng de piào.","translation":{"en":"I want one ticket to People''s Square.","fr":"Je voudrais un ticket pour la Place du Peuple."},"explanation":{"en":"一张 is the measure word for one ticket.","fr":"一张 est le classificateur pour un ticket."},"audio":"/audio/metro-ticket/line-03.mp3"},{"id":"metro-ticket-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"要几站？","pinyin":"Yào jǐ zhàn?","translation":{"en":"How many stops does it take?","fr":"Combien de stations faut-il ?"},"explanation":{"en":"要几站 is short and useful when you are counting stops.","fr":"要几站 est court et utile pour compter les stations."},"audio":"/audio/metro-ticket/line-04.mp3"},{"id":"metro-ticket-line-05","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"三站。","pinyin":"Sān zhàn.","translation":{"en":"Three stops.","fr":"Trois stations."},"explanation":{"en":"Listen for a number plus 站 when someone answers.","fr":"Écoute un nombre suivi de 站 quand quelqu''un répond."},"audio":"/audio/metro-ticket/line-05.mp3"},{"id":"metro-ticket-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"需要换乘吗？","pinyin":"Xūyào huànchéng ma?","translation":{"en":"Do I need to transfer?","fr":"Dois-je faire une correspondance ?"},"explanation":{"en":"Ask 需要换乘吗 to confirm if the route needs a transfer.","fr":"Demande 需要换乘吗 pour confirmer si le trajet nécessite une correspondance."},"audio":"/audio/metro-ticket/line-06.mp3"},{"id":"metro-ticket-line-07","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"不需要，一共三块钱。","pinyin":"Bù xūyào, yígòng sān kuài qián.","translation":{"en":"No transfer needed, three yuan in total.","fr":"Pas de correspondance, trois yuans au total."},"explanation":{"en":"The clerk confirms no transfer and gives the fare price.","fr":"L''employé confirme qu''il n''y a pas de correspondance et donne le prix."},"audio":"/audio/metro-ticket/line-07.mp3"},{"id":"metro-ticket-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"哪个出口出去？","pinyin":"Nǎge chūkǒu chūqù?","translation":{"en":"Which exit should I take?","fr":"Quelle sortie dois-je prendre ?"},"explanation":{"en":"Ask 哪个出口 when you arrive and need the right exit for your destination.","fr":"Demande 哪个出口 à l''arrivée pour trouver la bonne sortie vers ta destination."},"audio":"/audio/metro-ticket/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(76, 'metro-ticket', 'dialogue', '{"title":{"en":"Ask for a route and ticket","fr":"Demander un itinéraire et un ticket"},"lines":[{"id":"metro-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"去人民广场怎么走？","pinyin":"Qù Rénmín Guǎngchǎng zěnme zǒu?","translation":{"en":"How do I get to People''s Square?","fr":"Comment aller à la Place du Peuple ?"},"explanation":{"en":"去……怎么走 is the basic route question for a station or place.","fr":"去……怎么走 est la question de base pour demander un itinéraire vers une station ou un lieu."},"audio":"/audio/metro-ticket/line-01.mp3"},{"id":"metro-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"坐二号线。","pinyin":"Zuò èr hào xiàn.","translation":{"en":"Take line two.","fr":"Prenez la ligne 2."},"explanation":{"en":"号线 names the numbered metro line.","fr":"号线 indique la ligne de métro numérotée."},"audio":"/audio/metro-ticket/line-02.mp3"},{"id":"metro-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我要一张去人民广场的票。","pinyin":"Wǒ yào yì zhāng qù Rénmín Guǎngchǎng de piào.","translation":{"en":"I want one ticket to People''s Square.","fr":"Je voudrais un ticket pour la Place du Peuple."},"explanation":{"en":"一张 is the measure word for one ticket.","fr":"一张 est le classificateur pour un ticket."},"audio":"/audio/metro-ticket/line-03.mp3"},{"id":"metro-ticket-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"要几站？","pinyin":"Yào jǐ zhàn?","translation":{"en":"How many stops does it take?","fr":"Combien de stations faut-il ?"},"explanation":{"en":"要几站 is short and useful when you are counting stops.","fr":"要几站 est court et utile pour compter les stations."},"audio":"/audio/metro-ticket/line-04.mp3"},{"id":"metro-ticket-line-05","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"三站。","pinyin":"Sān zhàn.","translation":{"en":"Three stops.","fr":"Trois stations."},"explanation":{"en":"Listen for a number plus 站 when someone answers.","fr":"Écoute un nombre suivi de 站 quand quelqu''un répond."},"audio":"/audio/metro-ticket/line-05.mp3"},{"id":"metro-ticket-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"需要换乘吗？","pinyin":"Xūyào huànchéng ma?","translation":{"en":"Do I need to transfer?","fr":"Dois-je faire une correspondance ?"},"explanation":{"en":"Ask 需要换乘吗 to confirm if the route needs a transfer.","fr":"Demande 需要换乘吗 pour confirmer si le trajet nécessite une correspondance."},"audio":"/audio/metro-ticket/line-06.mp3"},{"id":"metro-ticket-line-07","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"不需要，一共三块钱。","pinyin":"Bù xūyào, yígòng sān kuài qián.","translation":{"en":"No transfer needed, three yuan in total.","fr":"Pas de correspondance, trois yuans au total."},"explanation":{"en":"The clerk confirms no transfer and gives the fare price.","fr":"L''employé confirme qu''il n''y a pas de correspondance et donne le prix."},"audio":"/audio/metro-ticket/line-07.mp3"},{"id":"metro-ticket-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"哪个出口出去？","pinyin":"Nǎge chūkǒu chūqù?","translation":{"en":"Which exit should I take?","fr":"Quelle sortie dois-je prendre ?"},"explanation":{"en":"Ask 哪个出口 when you arrive and need the right exit for your destination.","fr":"Demande 哪个出口 à l''arrivée pour trouver la bonne sortie vers ta destination."},"audio":"/audio/metro-ticket/line-08.mp3"}]}', 'draft', 75, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(77, 'metro-ticket', 'sentencePatterns', '[{"id":"metro-ticket-pattern-1","pattern":"去……怎么走？","meaning":{"en":"How do I get to ...?","fr":"Comment aller à ... ?"},"example":"去人民广场怎么走？","audio":"/audio/metro-ticket/pattern-01.mp3","explanation":{"en":"Use it before buying a ticket if you need the route.","fr":"Utilise cette structure avant d''acheter un ticket si tu as besoin de l''itinéraire."}},{"id":"metro-ticket-pattern-2","pattern":"我要一张去……的票。","meaning":{"en":"I want one ticket to ...","fr":"Je voudrais un ticket pour ..."},"example":"我要一张去人民广场的票。","audio":"/audio/metro-ticket/pattern-02.mp3","explanation":{"en":"This joins the ticket request and destination in one sentence.","fr":"Cette phrase relie la demande de ticket et la destination."}},{"id":"metro-ticket-pattern-3","pattern":"要几站？","meaning":{"en":"How many stops?","fr":"Combien de stations ?"},"example":"要几站？","audio":"/audio/metro-ticket/pattern-03.mp3","explanation":{"en":"Ask it after you know the metro line.","fr":"Pose cette question après connaître la ligne de métro."}},{"id":"metro-ticket-pattern-4","pattern":"需要……吗？","meaning":{"en":"Do I need ...? / Is ... needed?","fr":"Dois-je ... ? / ... est-il nécessaire ?"},"example":"需要换乘吗？","audio":"/audio/metro-ticket/pattern-04.mp3","explanation":{"en":"Use 需要…吗 to confirm if something is required.","fr":"Utilise 需要…吗 pour confirmer si quelque chose est nécessaire."}},{"id":"metro-ticket-pattern-5","pattern":"哪个……？","meaning":{"en":"Which ...?","fr":"Quel / Quelle ... ?"},"example":"哪个出口出去？","audio":"/audio/metro-ticket/pattern-05.mp3","explanation":{"en":"Use 哪个 to ask which one among visible options like exits or platforms.","fr":"Utilise 哪个 pour demander lequel parmi des options visibles comme les sorties ou les quais."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(78, 'metro-ticket', 'sentencePatterns', '[{"id":"metro-ticket-pattern-1","pattern":"去……怎么走？","meaning":{"en":"How do I get to ...?","fr":"Comment aller à ... ?"},"example":"去人民广场怎么走？","audio":"/audio/metro-ticket/pattern-01.mp3","explanation":{"en":"Use it before buying a ticket if you need the route.","fr":"Utilise cette structure avant d''acheter un ticket si tu as besoin de l''itinéraire."}},{"id":"metro-ticket-pattern-2","pattern":"我要一张去……的票。","meaning":{"en":"I want one ticket to ...","fr":"Je voudrais un ticket pour ..."},"example":"我要一张去人民广场的票。","audio":"/audio/metro-ticket/pattern-02.mp3","explanation":{"en":"This joins the ticket request and destination in one sentence.","fr":"Cette phrase relie la demande de ticket et la destination."}},{"id":"metro-ticket-pattern-3","pattern":"要几站？","meaning":{"en":"How many stops?","fr":"Combien de stations ?"},"example":"要几站？","audio":"/audio/metro-ticket/pattern-03.mp3","explanation":{"en":"Ask it after you know the metro line.","fr":"Pose cette question après connaître la ligne de métro."}},{"id":"metro-ticket-pattern-4","pattern":"需要……吗？","meaning":{"en":"Do I need ...? / Is ... needed?","fr":"Dois-je ... ? / ... est-il nécessaire ?"},"example":"需要换乘吗？","audio":"/audio/metro-ticket/pattern-04.mp3","explanation":{"en":"Use 需要…吗 to confirm if something is required.","fr":"Utilise 需要…吗 pour confirmer si quelque chose est nécessaire."}},{"id":"metro-ticket-pattern-5","pattern":"哪个……？","meaning":{"en":"Which ...?","fr":"Quel / Quelle ... ?"},"example":"哪个出口出去？","audio":"/audio/metro-ticket/pattern-05.mp3","explanation":{"en":"Use 哪个 to ask which one among visible options like exits or platforms.","fr":"Utilise 哪个 pour demander lequel parmi des options visibles comme les sorties ou les quais."}}]', 'draft', 77, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(79, 'metro-ticket', 'vocabulary', '[{"id":"metro-ticket-vocab-1","hanzi":"地铁","pinyin":"dìtiě","audio":"/audio/metro-ticket/vocab-01.mp3","meaning":{"en":"metro / subway","fr":"métro"},"explanation":{"en":"The transportation system for this lesson.","fr":"Le moyen de transport de cette leçon."}},{"id":"metro-ticket-vocab-2","hanzi":"票","pinyin":"piào","audio":"/audio/metro-ticket/vocab-02.mp3","meaning":{"en":"ticket","fr":"ticket / billet"},"explanation":{"en":"A shared word for metro and train tickets.","fr":"Un mot commun pour les tickets de métro et billets de train."}},{"id":"metro-ticket-vocab-3","hanzi":"站","pinyin":"zhàn","audio":"/audio/metro-ticket/vocab-03.mp3","meaning":{"en":"stop / station","fr":"station / arrêt"},"explanation":{"en":"Count stops with a number plus 站.","fr":"Compte les stations avec un nombre suivi de 站."}},{"id":"metro-ticket-vocab-4","hanzi":"二号线","pinyin":"èr hào xiàn","audio":"/audio/metro-ticket/vocab-04.mp3","meaning":{"en":"Line 2","fr":"ligne 2"},"explanation":{"en":"A model phrase for numbered metro lines.","fr":"Une phrase modèle pour les lignes de métro numérotées."}},{"id":"metro-ticket-vocab-5","hanzi":"换乘","pinyin":"huànchéng","audio":"/audio/metro-ticket/vocab-05.mp3","meaning":{"en":"transfer","fr":"correspondance"},"explanation":{"en":"Recognize it on signs even if this first route stays simple.","fr":"Reconnais-le sur les panneaux même si ce premier trajet reste simple."}},{"id":"metro-ticket-vocab-6","hanzi":"出口","pinyin":"chūkǒu","audio":"/audio/metro-ticket/vocab-06.mp3","meaning":{"en":"exit","fr":"sortie"},"explanation":{"en":"Look for 出口 signs to leave the station.","fr":"Cherche les panneaux 出口 pour sortir de la station."}},{"id":"metro-ticket-vocab-7","hanzi":"公交卡","pinyin":"gōngjiāokǎ","audio":"/audio/metro-ticket/vocab-07.mp3","meaning":{"en":"transit card","fr":"carte de transport"},"explanation":{"en":"A rechargeable card for bus and metro rides.","fr":"Une carte rechargeable pour les trajets en bus et métro."}},{"id":"metro-ticket-vocab-8","hanzi":"一张","pinyin":"yì zhāng","audio":"/audio/metro-ticket/vocab-08.mp3","meaning":{"en":"one (for flat items like tickets)","fr":"un (pour les objets plats comme les tickets)"},"explanation":{"en":"Use 张 for tickets, paper, and flat objects.","fr":"Utilise 张 pour les tickets, le papier et les objets plats."}},{"id":"metro-ticket-vocab-9","hanzi":"充值","pinyin":"chōngzhí","audio":"/audio/metro-ticket/vocab-09.mp3","meaning":{"en":"top up / recharge","fr":"recharger"},"explanation":{"en":"Use 充值 to add money to your transit card.","fr":"Utilise 充值 pour ajouter de l''argent à ta carte de transport."}},{"id":"metro-ticket-vocab-10","hanzi":"方向","pinyin":"fāngxiàng","audio":"/audio/metro-ticket/vocab-10.mp3","meaning":{"en":"direction","fr":"direction"},"explanation":{"en":"Check 方向 on metro signs to know which platform to take.","fr":"Vérifie 方向 sur les panneaux de métro pour savoir quel quai prendre."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
