on":{"en":"A short clear answer to the allergy safety question.","fr":"Une réponse courte et claire à la question de sécurité sur les allergies."},"audio":"/audio/pharmacy-help/line-05.mp3"},{"id":"pharmacy-help-line-06","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"这个止疼药，一次一片，一天两次。","pinyin":"Zhège zhǐténg yào, yí cì yí piàn, yì tiān liǎng cì.","translation":{"en":"This painkiller, one tablet per dose, twice a day.","fr":"Cet antidouleur, un comprimé par prise, deux fois par jour."},"explanation":{"en":"一次一片 adds the dosage detail on top of the frequency.","fr":"一次一片 ajoute le détail du dosage en plus de la fréquence."},"audio":"/audio/pharmacy-help/line-06.mp3"},{"id":"pharmacy-help-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"饭前吃还是饭后吃？","pinyin":"Fàn qián chī háishi fàn hòu chī?","translation":{"en":"Take before or after meals?","fr":"Prendre avant ou après les repas ?"},"explanation":{"en":"饭前/饭后 is a common instruction to check for any medicine.","fr":"饭前/饭后 est une consigne courante à vérifier pour tout médicament."},"audio":"/audio/pharmacy-help/line-07.mp3"},{"id":"pharmacy-help-line-08","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"饭后吃。一共十八块钱。","pinyin":"Fàn hòu chī. Yígòng shíbā kuài qián.","translation":{"en":"After meals. Eighteen yuan altogether.","fr":"Après les repas. Dix-huit yuans au total."},"explanation":{"en":"The pharmacist gives the instruction and the price together.","fr":"Le pharmacien donne la consigne et le prix ensemble."},"audio":"/audio/pharmacy-help/line-08.mp3"}]}', 'draft', 87, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(89, 'pharmacy-help', 'sentencePatterns', '[{"id":"pharmacy-help-pattern-1","pattern":"我……疼。","meaning":{"en":"My ... hurts.","fr":"J’ai mal à ..."},"example":"我头疼。","audio":"/audio/pharmacy-help/pattern-01.mp3","explanation":{"en":"Put the body part before 疼 for a simple symptom.","fr":"Place la partie du corps avant 疼 pour un symptôme simple."}},{"id":"pharmacy-help-pattern-2","pattern":"你……吗？","meaning":{"en":"Do you ...?","fr":"Est-ce que vous ... ?"},"example":"你发烧吗？","audio":"/audio/pharmacy-help/pattern-02.mp3","explanation":{"en":"Listen for 吗 when a clerk asks a yes/no health question.","fr":"Écoute 吗 quand un employé pose une question de santé oui/non."}},{"id":"pharmacy-help-pattern-3","pattern":"一次……片。","meaning":{"en":"... tablet(s) per dose.","fr":"... comprimé(s) par prise."},"example":"一次一片。","audio":"/audio/pharmacy-help/pattern-03.mp3","explanation":{"en":"This tells you how many pills to take at one time.","fr":"Cela indique combien de pilules prendre en une fois."}},{"id":"pharmacy-help-pattern-4","pattern":"我对……过敏。","meaning":{"en":"I am allergic to ...","fr":"Je suis allergique à ..."},"example":"我对青霉素过敏。","audio":"/audio/pharmacy-help/pattern-04.mp3","explanation":{"en":"Use this to name a specific allergy if asked.","fr":"Utilise cette structure pour nommer une allergie spécifique si on te le demande."}},{"id":"pharmacy-help-pattern-5","pattern":"饭前还是饭后？","meaning":{"en":"Before or after meals?","fr":"Avant ou après les repas ?"},"example":"饭前还是饭后？","audio":"/audio/pharmacy-help/pattern-05.mp3","explanation":{"en":"Ask this to confirm when to take the medicine.","fr":"Demande cela pour confirmer quand prendre le médicament."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
