(91, 'pharmacy-help', 'vocabulary', '[{"id":"pharmacy-help-vocab-1","hanzi":"药店","pinyin":"yàodiàn","audio":"/audio/pharmacy-help/vocab-01.mp3","meaning":{"en":"pharmacy","fr":"pharmacie"},"explanation":{"en":"The place to ask for simple medicine help.","fr":"Le lieu pour demander une aide simple avec un médicament."}},{"id":"pharmacy-help-vocab-2","hanzi":"药","pinyin":"yào","audio":"/audio/pharmacy-help/vocab-02.mp3","meaning":{"en":"medicine","fr":"médicament"},"explanation":{"en":"A core word in pharmacy instructions.","fr":"Un mot essentiel dans les consignes de pharmacie."}},{"id":"pharmacy-help-vocab-3","hanzi":"头疼","pinyin":"tóu téng","audio":"/audio/pharmacy-help/vocab-03.mp3","meaning":{"en":"headache","fr":"mal à la tête"},"explanation":{"en":"The mild symptom used in the dialogue.","fr":"Le symptôme léger utilisé dans le dialogue."}},{"id":"pharmacy-help-vocab-4","hanzi":"发烧","pinyin":"fāshāo","audio":"/audio/pharmacy-help/vocab-04.mp3","meaning":{"en":"to have a fever","fr":"avoir de la fièvre"},"explanation":{"en":"A common follow-up symptom question.","fr":"Une question de symptôme fréquente."}},{"id":"pharmacy-help-vocab-5","hanzi":"过敏","pinyin":"guòmǐn","audio":"/audio/pharmacy-help/vocab-05.mp3","meaning":{"en":"allergy / allergic","fr":"allergie / allergique"},"explanation":{"en":"A safety word to recognize even in a mild-health lesson.","fr":"Un mot de sécurité à reconnaître même dans une leçon de santé légère."}},{"id":"pharmacy-help-vocab-6","hanzi":"肚子疼","pinyin":"dùzi téng","audio":"/audio/pharmacy-help/vocab-06.mp3","meaning":{"en":"stomach ache","fr":"mal au ventre"},"explanation":{"en":"Another common symptom to report at the pharmacy.","fr":"Un autre symptôme courant à signaler à la pharmacie."}},{"id":"pharmacy-help-vocab-7","hanzi":"止疼药","pinyin":"zhǐténg yào","audio":"/audio/pharmacy-help/vocab-07.mp3","meaning":{"en":"painkiller","fr":"antidouleur"},"explanation":{"en":"The kind of medicine you might ask for with a headache.","fr":"Le type de médicament que tu pourrais demander pour un mal de tête."}},{"id":"pharmacy-help-vocab-8","hanzi":"一次一片","pinyin":"yí cì yí piàn","audio":"/audio/pharmacy-help/vocab-08.mp3","meaning":{"en":"one tablet per dose","fr":"un comprimé par prise"},"explanation":{"en":"The dosage instruction you will hear with medicine.","fr":"La consigne de dosage que tu entendras avec le médicament."}},{"id":"pharmacy-help-vocab-9","hanzi":"饭前","pinyin":"fàn qián","audio":"/audio/pharmacy-help/vocab-09.mp3","meaning":{"en":"before meals","fr":"avant les repas"},"explanation":{"en":"One of the two common medicine timing words.","fr":"Un des deux mots courants pour le moment de prise du médicament."}},{"id":"pharmacy-help-vocab-10","hanzi":"饭后","pinyin":"fàn hòu","audio":"/audio/pharmacy-help/vocab-10.mp3","meaning":{"en":"after meals","fr":"après les repas"},"explanation":{"en":"The other common medicine timing word paired with 饭前.","fr":"L’autre mot courant pour le moment de prise, associé à 饭前."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(92, 'pharmacy-help', 'vocabulary', '[{"id":"pharmacy-help-vocab-1","hanzi":"药店","pinyin":"yàodiàn","audio":"/audio/pharmacy-help/vocab-01.mp3","meaning":{"en":"pharmacy","fr":"pharmacie"},"explanation":{"en":"The place to ask for simple medicine help.","fr":"Le lieu pour demander une aide simple avec un médicament."}},{"id":"pharmacy-help-vocab-2","hanzi":"药","pinyin":"yào","audio":"/audio/pharmacy-help/vocab-02.mp3","meaning":{"en":"medicine","fr":"médicament"},"explanation":{"en":"A core word in pharmacy instructions.","fr":"Un mot essentiel dans les consignes de pharmacie."}},{"id":"pharmacy-help-vocab-3","hanzi":"头疼","pinyin":"tóu téng","audio":"/audio/pharmacy-help/vocab-03.mp3","meaning":{"en":"headache","fr":"mal à la tête"},"explanation":{"en":"The mild symptom used in the dialogue.","fr":"Le symptôme léger utilisé dans le dialogue."}},{"id":"pharmacy-help-vocab-4","hanzi":"发烧","pinyin":"fāshāo","audio":"/audio/pharmacy-help/vocab-04.mp3","meaning":{"en":"to have a fever","fr":"avoir de la fièvre"},"explanation":{"en":"A common follow-up symptom question.","fr":"Une question de symptôme fréquente."}},{"id":"pharmacy-help-vocab-5","hanzi":"过敏","pinyin":"guòmǐn","audio":"/audio/pharmacy-help/vocab-05.mp3","meaning":{"en":"allergy / allergic","fr":"allergie / allergique"},"explanation":{"en":"A safety word to recognize even in a mild-health lesson.","fr":"Un mot de sécurité à reconnaître même dans une leçon de santé légère."}},{"id":"pharmacy-help-vocab-6","hanzi":"肚子疼","pinyin":"dùzi téng","audio":"/audio/pharmacy-help/vocab-06.mp3","meaning":{"en":"stomach ache","fr":"mal au ventre"},"explanation":{"en":"Another common symptom to report at the pharmacy.","fr":"Un autre symptôme courant à signaler à la pharmacie."}},{"id":"pharmacy-help-vocab-7","hanzi":"止疼药","pinyin":"zhǐténg yào","audio":"/audio/pharmacy-help/vocab-07.mp3","meaning":{"en":"painkiller","fr":"antidouleur"},"explanation":{"en":"The kind of medicine you might ask for with a headache.","fr":"Le type de médicament que tu pourrais demander pour un mal de tête."}},{"id":"pharmacy-help-vocab-8","hanzi":"一次一片","pinyin":"yí cì yí piàn","audio":"/audio/pharmacy-help/vocab-08.mp3","meaning":{"en":"one tablet per dose","fr":"un comprimé par prise"},"explanation":{"en":"The dosage instruction you will hear with medicine.","fr":"La consigne de dosage que tu entendras avec le médicament."}},{"id":"pharmacy-help-vocab-9","hanzi":"饭前","pinyin":"fàn qián","audio":"/audio/pharmacy-help/vocab-09.mp3","meaning":{"en":"before meals","fr":"avant les repas"},"explanation":{"en":"One of the two common medicine timing words.","fr":"Un des deux mots courants pour le moment de prise du médicament."}},{"id":"pharmacy-help-vocab-10","hanzi":"饭后","pinyin":"fàn hòu","audio":"/audio/pharmacy-help/vocab-10.mp3","meaning":{"en":"after meals","fr":"après les repas"},"explanation":{"en":"The other common medicine timing word paired with 饭前.","fr":"L’autre mot courant pour le moment de prise, associé à 饭前."}}]', 'draft', 91, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(93, 'pharmacy-help', 'practice', '{"listening":[{"id":"pharmacy-help-listening-1","prompt":{"en":"Listen for headache and no fever.","fr":"Écoute “mal à la tête” et “pas de fièvre”."},"target":"我头疼，不发烧。","audio":"/audio/pharmacy-help/practice-listening-01.mp3","explanation":{"en":"This combines the symptom and the negative fever answer.","fr":"Cela combine le symptôme et la réponse négative sur la fièvre."}},{"id":"pharmacy-help-listening-2","prompt":{"en":"Which phrase asks about allergies?","fr":"Quelle phrase demande à propos des allergies ?"},"target":"你对什么过敏吗？","audio":"/audio/pharmacy-help/practice-listening-02.mp3","explanation":{"en":"This is a safety question you will hear at the pharmacy.","fr":"C’est une question de sécurité que tu entendras à la pharmacie."}}],"speaking":[{"id":"pharmacy-help-speaking-1","prompt":{"en":"Say that your head hurts.","fr":"Dis que tu as mal à la tête."},"target":"我头疼。","audio":"/audio/pharmacy-help/practice-speaking-01.mp3","explanation":{"en":"Start with the shortest clear symptom sentence.","fr":"Commence par la phrase de symptôme la plus courte et claire."}},{"id":"pharmacy-help-speaking-2","prompt":{"en":"Ask whether to take the medicine before or after meals.","fr":"Demande si le médicament se prend avant ou après les repas."},"target":"饭前还是饭后？","audio":"/audio/pharmacy-help/practice-speaking-02.mp3","explanation":{"en":"This confirms the correct timing for the medicine.","fr":"Cela confirme le bon moment pour prendre le médicament."}}],"reading":[{"id":"pharmacy-help-reading-1","prompt":{"en":"Read the medicine frequency phrase.","fr":"Lis la phrase de fréquence du médicament."},"target":"一天两次。","audio":"/audio/pharmacy-help/practice-reading-01.mp3","explanation":{"en":"Recognize how many times per day the medicine is used.","fr":"Reconnais combien de fois par jour le médicament est utilisé."}},{"id":"pharmacy-help-reading-2","prompt":{"en":"Match the dosage instruction.","fr":"Associe la consigne de dosage."},"target":"一次一片","audio":"/audio/pharmacy-help/practice-reading-02.mp3","explanation":{"en":"一次一片 is the pill count per dose.","fr":"一次一片 est le nombre de comprimés par prise."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(94, 'pharmacy-help', 'practice', '{"listening":[{"id":"pharmacy-help-listening-1","prompt":{"en":"Listen for headache and no fever.","fr":"Écoute “mal à la tête” et “pas de fièvre”."},"target":"我头疼，不发烧。","audio":"/audio/pharmacy-help/practice-listening-01.mp3","explanation":{"en":"This combines the symptom and the negative fever answer.","fr":"Cela combine le symptôme et la réponse négative sur la fièvre."}},{"id":"pharmacy-help-listening-2","prompt":{"en":"Which phrase asks about allergies?","fr":"Quelle phrase demande à propos des allergies ?"},"target":"你对什么过敏吗？","audio":"/audio/pharmacy-help/practice-listening-02.mp3","explanation":{"en":"This is a safety question you will hear at the pharmacy.","fr":"C’est une question de sécurité que tu entendras à la pharmacie."}}],"speaking":[{"id":"pharmacy-help-speaking-1","prompt":{"en":"Say that your head hurts.","fr":"Dis que tu as mal à la tête."},"target":"我头疼。","audio":"/audio/pharmacy-help/practice-speaking-01.mp3","explanation":{"en":"Start with the shortest clear symptom sentence.","fr":"Commence par la phrase de symptôme la plus courte et claire."}},{"id":"pharmacy-help-speaking-2","prompt":{"en":"Ask whether to take the medicine before or after meals.","fr":"Demande si le médicament se prend avant ou après les repas."},"target":"饭前还是饭后？","audio":"/audio/pharmacy-help/practice-speaking-02.mp3","explanation":{"en":"This confirms the correct timing for the medicine.","fr":"Cela confirme le bon moment pour prendre le médicament."}}],"reading":[{"id":"pharmacy-help-reading-1","prompt":{"en":"Read the medicine frequency phrase.","fr":"Lis la phrase de fréquence du médicament."},"target":"一天两次。","audio":"/audio/pharmacy-help/practice-reading-01.mp3","explanation":{"en":"Recognize how many times per day the medicine is used.","fr":"Reconnais combien de fois par jour le médicament est utilisé."}},{"id":"pharmacy-help-reading-2","prompt":{"en":"Match the dosage instruction.","fr":"Associe la consigne de dosage."},"target":"一次一片","audio":"/audio/pharmacy-help/practice-reading-02.mp3","explanation":{"en":"一次一片 is the pill count per dose.","fr":"一次一片 est le nombre de comprimés par prise."}}]}', 'draft', 93, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(95, 'pharmacy-help', 'reviewCards', '[{"id":"pharmacy-help-review-1","front":"药店","back":{"en":"pharmacy","fr":"pharmacie"},"explanation":{"en":"The place for the help request.","fr":"Le lieu de la demande d’aide."}},{"id":"pharmacy-help-review-2","front":"头疼","back":{"en":"headache","fr":"mal à la tête"},"explanation":{"en":"Say 我头疼 to report it.","fr":"Dis 我头疼 pour le signaler."}},{"id":"pharmacy-help-review-3","front":"一天两次","back":{"en":"twice a day","fr":"deux fois par jour"},"explanation":{"en":"A common medicine frequency.","fr":"Une fréquence courante pour un médicament."}},{"id":"pharmacy-help-review-4","front":"肚子疼","back":{"en":"stomach ache","fr":"mal au ventre"},"explanation":{"en":"Another symptom you can report with 我……疼.","fr":"Un autre symptôme que tu peux signaler avec 我……疼."}},{"id":"pharmacy-help-review-5","front":"过敏","back":{"en":"allergy / allergic","fr":"allergie / allergique"},"explanation":{"en":"A safety word the pharmacist will check.","fr":"Un mot de sécurité que le pharmacien vérifiera."}},{"id":"pharmacy-help-review-6","front":"饭后","back":{"en":"after meals","fr":"après les repas"},"explanation":{"en":"A common medicine timing instruction.","fr":"Une consigne courante pour le moment de prise."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
