-2","prompt":{"en":"Match the phrase for \"no problem\".","fr":"Associe la phrase pour \"pas de problème\"."},"target":"没关系","audio":"/audio/ask-for-help-problem/practice-reading-02.mp3","explanation":{"en":"没关系 is a friendly go-to reply in many situations.","fr":"没关系 est une réponse amicale passe-partout dans de nombreuses situations."}}]}', 'draft', 105, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(107, 'ask-for-help-problem', 'reviewCards', '[{"id":"ask-for-help-problem-review-1","front":"帮我一下","back":{"en":"help me for a moment","fr":"aidez-moi un instant"},"explanation":{"en":"A polite core help request.","fr":"Une demande d’aide centrale et polie."}},{"id":"ask-for-help-problem-review-2","front":"有问题","back":{"en":"has a problem","fr":"a un problème"},"explanation":{"en":"Use it after the item with the issue.","fr":"Utilise-le après l’objet qui pose problème."}},{"id":"ask-for-help-problem-review-3","front":"慢一点","back":{"en":"a little slower","fr":"un peu plus lentement"},"explanation":{"en":"A repair phrase when speech is too fast.","fr":"Une phrase de réparation si la parole est trop rapide."}},{"id":"ask-for-help-problem-review-4","front":"没电","back":{"en":"out of battery","fr":"plus de batterie"},"explanation":{"en":"Say this when your phone is dead.","fr":"Dis ceci quand ton téléphone est déchargé."}},{"id":"ask-for-help-problem-review-5","front":"密码","back":{"en":"password","fr":"mot de passe"},"explanation":{"en":"Ask for this when connecting to WiFi.","fr":"Demande ceci pour te connecter au WiFi."}},{"id":"ask-for-help-problem-review-6","front":"没关系","back":{"en":"no problem","fr":"pas de problème"},"explanation":{"en":"A friendly reply that keeps the exchange relaxed.","fr":"Une réponse amicale qui garde l''échange détendu."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
