(109, 'train-station-ticket', 'lessonMeta', '{"id":"train-station-ticket","title":{"en":"Buy a train station ticket","fr":"Acheter un billet en gare"},"scenario":{"en":"Buy a train ticket to Shanghai, choose a date and seat type, show your passport, understand the platform and departure time, and ask about delays.","fr":"Acheter un billet de train pour Shanghai, choisir une date et un type de place, présenter son passeport, comprendre le quai et l''heure de départ, et se renseigner sur les retards."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(110, 'train-station-ticket', 'lessonMeta', '{"id":"train-station-ticket","title":{"en":"Buy a train station ticket","fr":"Acheter un billet en gare"},"scenario":{"en":"Buy a train ticket to Shanghai, choose a date and seat type, show your passport, understand the platform and departure time, and ask about delays.","fr":"Acheter un billet de train pour Shanghai, choisir une date et un type de place, présenter son passeport, comprendre le quai et l''heure de départ, et se renseigner sur les retards."}}', 'draft', 109, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(111, 'train-station-ticket', 'dialogue', '{"title":{"en":"Buy a train ticket and find your platform","fr":"Acheter un billet de train et trouver son quai"},"lines":[{"id":"train-station-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想买一张去上海的票。","pinyin":"Nǐ hǎo, wǒ xiǎng mǎi yì zhāng qù Shànghǎi de piào.","translation":{"en":"Hello, I would like to buy one ticket to Shanghai.","fr":"Bonjour, je voudrais acheter un billet pour Shanghai."},"explanation":{"en":"This capstone ticket phrase extends the metro ticket pattern with 我想买.","fr":"Cette phrase de billet finale prolonge le modèle du ticket de métro avec 我想买."},"audio":"/audio/train-station-ticket/line-01.mp3"},{"id":"train-station-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"今天还是明天？","pinyin":"Jīntiān háishi míngtiān?","translation":{"en":"Today or tomorrow?","fr":"Aujourd''hui ou demain ?"},"explanation":{"en":"还是 presents two choices in a question.","fr":"还是 présente deux choix dans une question."},"audio":"/audio/train-station-ticket/line-02.mp3"},{"id":"train-station-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"今天下午，有票吗？","pinyin":"Jīntiān xiàwǔ, yǒu piào ma?","translation":{"en":"This afternoon, are there tickets?","fr":"Cet après-midi, y a-t-il des billets ?"},"explanation":{"en":"有票吗 confirms availability for your chosen time.","fr":"有票吗 confirme la disponibilité pour l''horaire choisi."},"audio":"/audio/train-station-ticket/line-03.mp3"},{"id":"train-station-ticket-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有。硬座还是软座？","pinyin":"Yǒu. Yìngzuò háishi ruǎnzuò?","translation":{"en":"Yes. Hard seat or soft seat?","fr":"Oui. Place dure ou place molle ?"},"explanation":{"en":"硬座 is the basic seat; 软座 is more comfortable and costs more.","fr":"硬座 est la place de base ; 软座 est plus confortable et coûte plus cher."},"audio":"/audio/train-station-ticket/line-04.mp3"},{"id":"train-station-ticket-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"硬座。请出示护照吗？","pinyin":"Yìngzuò. Qǐng chūshì hùzhào ma?","translation":{"en":"Hard seat. Do I need to show my passport?","fr":"Place dure. Dois-je présenter mon passeport ?"},"explanation":{"en":"The traveler anticipates the passport requirement learned in earlier lessons.","fr":"Le voyageur anticipe la demande de passeport apprise dans les leçons précédentes."},"audio":"/audio/train-station-ticket/line-05.mp3"},{"id":"train-station-ticket-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"对，请出示护照。这是您的票。","pinyin":"Duì, qǐng chūshì hùzhào. Zhè shì nín de piào.","translation":{"en":"Yes, please show your passport. This is your ticket.","fr":"Oui, veuillez présenter votre passeport. Voici votre billet."},"explanation":{"en":"The clerk confirms the passport step and hands over the ticket.","fr":"L''employé confirme l''étape du passeport et remet le billet."},"audio":"/audio/train-station-ticket/line-06.mp3"},{"id":"train-station-ticket-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"在哪个站台？几点出发？","pinyin":"Zài nǎge zhàntái? Jǐ diǎn chūfā?","translation":{"en":"Which platform? What time does it depart?","fr":"Quel quai ? À quelle heure part-il ?"},"explanation":{"en":"站台 is the platform; 几点出发 asks for the exact departure time.","fr":"站台 est le quai ; 几点出发 demande l''heure exacte de départ."},"audio":"/audio/train-station-ticket/line-07.mp3"},{"id":"train-station-ticket-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"二号站台，三点出发。不会晚点。","pinyin":"Èr hào zhàntái, sān diǎn chūfā. Bú huì wǎndiǎn.","translation":{"en":"Platform two, departs at three o''clock. It won''t be delayed.","fr":"Quai numéro deux, départ à trois heures. Il n''y aura pas de retard."},"explanation":{"en":"不会晚点 reassures you that the train is on time.","fr":"不会晚点 te rassure que le train est à l''heure."},"audio":"/audio/train-station-ticket/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(112, 'train-station-ticket', 'dialogue', '{"title":{"en":"Buy a train ticket and find your platform","fr":"Acheter un billet de train et trouver son quai"},"lines":[{"id":"train-station-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想买一张去上海的票。","pinyin":"Nǐ hǎo, wǒ xiǎng mǎi yì zhāng qù Shànghǎi de piào.","translation":{"en":"Hello, I would like to buy one ticket to Shanghai.","fr":"Bonjour, je voudrais acheter un billet pour Shanghai."},"explanation":{"en":"This capstone ticket phrase extends the metro ticket pattern with 我想买.","fr":"Cette phrase de billet finale prolonge le modèle du ticket de métro avec 我想买."},"audio":"/audio/train-station-ticket/line-01.mp3"},{"id":"train-station-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"今天还是明天？","pinyin":"Jīntiān háishi míngtiān?","translation":{"en":"Today or tomorrow?","fr":"Aujourd''hui ou demain ?"},"explanation":{"en":"还是 presents two choices in a question.","fr":"还是 présente deux choix dans une question."},"audio":"/audio/train-station-ticket/line-02.mp3"},{"id":"train-station-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"今天下午，有票吗？","pinyin":"Jīntiān xiàwǔ, yǒu piào ma?","translation":{"en":"This afternoon, are there tickets?","fr":"Cet après-midi, y a-t-il des billets ?"},"explanation":{"en":"有票吗 confirms availability for your chosen time.","fr":"有票吗 confirme la disponibilité pour l''horaire choisi."},"audio":"/audio/train-station-ticket/line-03.mp3"},{"id":"train-station-ticket-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有。硬座还是软座？","pinyin":"Yǒu. Yìngzuò háishi ruǎnzuò?","translation":{"en":"Yes. Hard seat or soft seat?","fr":"Oui. Place dure ou place molle ?"},"explanation":{"en":"硬座 is the basic seat; 软座 is more comfortable and costs more.","fr":"硬座 est la place de base ; 软座 est plus confortable et coûte plus cher."},"audio":"/audio/train-station-ticket/line-04.mp3"},{"id":"train-station-ticket-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"硬座。请出示护照吗？","pinyin":"Yìngzuò. Qǐng chūshì hùzhào ma?","translation":{"en":"Hard seat. Do I need to show my passport?","fr":"Place dure. Dois-je présenter mon passeport ?"},"explanation":{"en":"The traveler anticipates the passport requirement learned in earlier lessons.","fr":"Le voyageur anticipe la demande de passeport apprise dans les leçons précédentes."},"audio":"/audio/train-station-ticket/line-05.mp3"},{"id":"train-station-ticket-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"对，请出示护照。这是您的票。","pinyin":"Duì, qǐng chūshì hùzhào. Zhè shì nín de piào.","translation":{"en":"Yes, please show your passport. This is your ticket.","fr":"Oui, veuillez présenter votre passeport. Voici votre billet."},"explanation":{"en":"The clerk confirms the passport step and hands over the ticket.","fr":"L''employé confirme l''étape du passeport et remet le billet."},"audio":"/audio/train-station-ticket/line-06.mp3"},{"id":"train-station-ticket-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"在哪个站台？几点出发？","pinyin":"Zài nǎge zhàntái? Jǐ diǎn chūfā?","translation":{"en":"Which platform? What time does it depart?","fr":"Quel quai ? À quelle heure part-il ?"},"explanation":{"en":"站台 is the platform; 几点出发 asks for the exact departure time.","fr":"站台 est le quai ; 几点出发 demande l''heure exacte de départ."},"audio":"/audio/train-station-ticket/line-07.mp3"},{"id":"train-station-ticket-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"二号站台，三点出发。不会晚点。","pinyin":"Èr hào zhàntái, sān diǎn chūfā. Bú huì wǎndiǎn.","translation":{"en":"Platform two, departs at three o''clock. It won''t be delayed.","fr":"Quai numéro deux, départ à trois heures. Il n''y aura pas de retard."},"explanation":{"en":"不会晚点 reassures you that the train is on time.","fr":"不会晚点 te rassure que le train est à l''heure."},"audio":"/audio/train-station-ticket/line-08.mp3"}]}', 'draft', 111, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(113, 'train-station-ticket', 'sentencePatterns', '[{"id":"train-station-ticket-pattern-1","pattern":"我想买一张去……的票。","meaning":{"en":"I would like to buy one ticket to ...","fr":"Je voudrais acheter un billet pour ..."},"example":"我想买一张去上海的票。","audio":"/audio/train-station-ticket/pattern-01.mp3","explanation":{"en":"Use this at a ticket counter with the destination in the middle.","fr":"Utilise cette phrase au guichet avec la destination au milieu."}},{"id":"train-station-ticket-pattern-2","pattern":"……还是……？","meaning":{"en":"... or ...?","fr":"... ou ... ?"},"example":"硬座还是软座？","audio":"/audio/train-station-ticket/pattern-02.mp3","explanation":{"en":"还是 offers you a choice between two options.","fr":"还是 te propose un choix entre deux options."}},{"id":"train-station-ticket-pattern-3","pattern":"在哪个站台？","meaning":{"en":"Which platform?","fr":"Quel quai ?"},"example":"在哪个站台？","audio":"/audio/train-station-ticket/pattern-03.mp3","explanation":{"en":"Ask this to find where your train will board.","fr":"Demande cela pour trouver où ton train embarque."}},{"id":"train-station-ticket-pattern-4","pattern":"有……的票吗？","meaning":{"en":"Are there tickets for ...?","fr":"Y a-t-il des billets pour ... ?"},"example":"有今天下午的票吗？","audio":"/audio/train-station-ticket/pattern-04.mp3","explanation":{"en":"Use this to check availability for a specific time.","fr":"Utilise cette structure pour vérifier la disponibilité d''un horaire précis."}},{"id":"train-station-ticket-pattern-5","pattern":"不会晚点。","meaning":{"en":"It won''t be delayed.","fr":"Il n''y aura pas de retard."},"example":"不会晚点。","audio":"/audio/train-station-ticket/pattern-05.mp3","explanation":{"en":"Listen for this reassuring phrase about train punctuality.","fr":"Écoute cette phrase rassurante sur la ponctualité du train."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
