(115, 'train-station-ticket', 'vocabulary', '[{"id":"train-station-ticket-vocab-1","hanzi":"火车站","pinyin":"huǒchēzhàn","audio":"/audio/train-station-ticket/vocab-01.mp3","meaning":{"en":"train station","fr":"gare"},"explanation":{"en":"The place for this capstone ticketing scene.","fr":"Le lieu de cette scène finale d''achat de billet."}},{"id":"train-station-ticket-vocab-2","hanzi":"车票","pinyin":"chēpiào","audio":"/audio/train-station-ticket/vocab-02.mp3","meaning":{"en":"train ticket / vehicle ticket","fr":"billet de train / ticket de transport"},"explanation":{"en":"A ticket word you will see at stations.","fr":"Un mot de billet que tu verras en gare."}},{"id":"train-station-ticket-vocab-3","hanzi":"上海","pinyin":"Shànghǎi","audio":"/audio/train-station-ticket/vocab-03.mp3","meaning":{"en":"Shanghai","fr":"Shanghai"},"explanation":{"en":"The model destination in the ticket request.","fr":"La destination modèle dans la demande de billet."}},{"id":"train-station-ticket-vocab-4","hanzi":"今天","pinyin":"jīntiān","audio":"/audio/train-station-ticket/vocab-04.mp3","meaning":{"en":"today","fr":"aujourd''hui"},"explanation":{"en":"The date answer paired with 明天.","fr":"La réponse de date associée à 明天."}},{"id":"train-station-ticket-vocab-5","hanzi":"出发","pinyin":"chūfā","audio":"/audio/train-station-ticket/vocab-05.mp3","meaning":{"en":"depart","fr":"partir / départ"},"explanation":{"en":"The action word for the train leaving.","fr":"Le mot d''action pour le départ du train."}},{"id":"train-station-ticket-vocab-6","hanzi":"硬座","pinyin":"yìngzuò","audio":"/audio/train-station-ticket/vocab-06.mp3","meaning":{"en":"hard seat (basic class)","fr":"place dure (classe de base)"},"explanation":{"en":"The most common and affordable train seat type.","fr":"Le type de place le plus courant et abordable en train."}},{"id":"train-station-ticket-vocab-7","hanzi":"软座","pinyin":"ruǎnzuò","audio":"/audio/train-station-ticket/vocab-07.mp3","meaning":{"en":"soft seat (comfort class)","fr":"place molle (classe confort)"},"explanation":{"en":"A more comfortable seat option that costs a bit more.","fr":"Une option de place plus confortable qui coûte un peu plus cher."}},{"id":"train-station-ticket-vocab-8","hanzi":"站台","pinyin":"zhàntái","audio":"/audio/train-station-ticket/vocab-08.mp3","meaning":{"en":"platform","fr":"quai"},"explanation":{"en":"The place where you board the train.","fr":"L''endroit où tu montes dans le train."}},{"id":"train-station-ticket-vocab-9","hanzi":"晚点","pinyin":"wǎndiǎn","audio":"/audio/train-station-ticket/vocab-09.mp3","meaning":{"en":"delay / late","fr":"retard / en retard"},"explanation":{"en":"A word you will see on station displays if a train is late.","fr":"Un mot que tu verras sur les écrans de gare si un train est en retard."}},{"id":"train-station-ticket-vocab-10","hanzi":"护照","pinyin":"hùzhào","audio":"/audio/train-station-ticket/vocab-10.mp3","meaning":{"en":"passport","fr":"passeport"},"explanation":{"en":"You need it for buying long-distance train tickets.","fr":"Tu en as besoin pour acheter des billets de train longue distance."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
